mapper.select:
SELECT COUNT(*) FROM sa_quiz
WHERE user_id = #{userId}
AND title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{status}

SELECT id, user_id, knowledge_base_id, title, topic, difficulty, question_count, types_json,
       status, score, correct_count, wrong_count, analysis, error_message,
       create_time, update_time, submitted_at
FROM sa_quiz
WHERE user_id = #{userId}
AND title LIKE CONCAT('%', #{keyword}, '%')
AND status = #{status}
ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE sa_quiz SET status = 'FAILED', error_message = #{errorMessage}
WHERE status IN ('PROCESSING')
  AND update_time < TIMESTAMPADD(SECOND, -#{timeoutSeconds}, CURRENT_TIMESTAMP)
ORDER BY update_time, id LIMIT #{batchSize}
